"""Compact read-only owner workspace, one CSP-hashed script, no remote assets."""
from .quant_share_ui import HTML as SHARES

STYLE=SHARES.split('<style>')[1].split('</style>')[0]
HTML='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>账务核验 · 稻草财经</title><style>'''+STYLE+r'''
header{height:52px}header nav{display:flex;gap:14px;font-size:12px}.workspace{padding-top:18px}h1{font-size:23px}.intro{margin-bottom:16px}.result{border-top:1px solid var(--line);padding:20px 0 6px}.result:first-of-type{border-top:0}.resulthead{display:flex;justify-content:space-between;gap:14px;align-items:start}.return{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.return strong{font-size:25px;display:block;line-height:1.25}.return small{color:var(--muted);font-size:11px}.checkgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:16px 0}.check{border:1px solid var(--line);border-radius:9px;padding:12px}.check small{display:block;color:var(--muted);font-size:11px}.check b{font-size:15px}.failed{color:#b74c56}.verified{color:var(--accent)}.loss{color:#16836a}.stats{font-size:12px;color:var(--muted);margin:12px 0}.differences{width:100%;border-collapse:collapse;font-size:12px}.differences td,.differences th{border-bottom:1px solid var(--line);padding:10px 8px;text-align:left;font-variant-numeric:tabular-nums}.differences th{font-weight:500;color:var(--muted)}.tablewrap{overflow:auto;max-width:100%}.differences th,.differences td{white-space:nowrap}#detail:focus{outline:2px solid var(--accent);outline-offset:3px}.record b{font-size:13px}.panel>h2{overflow-wrap:anywhere}.meta{display:flex;gap:12px;flex-wrap:wrap;margin:6px 0}.empty{min-height:240px}.notice{margin:12px 0}.result .notice{margin-bottom:0}@media(max-width:700px){header{padding:0 12px}header nav{gap:10px}.workspace{padding-top:14px}.intro{align-items:start}h1{font-size:21px}.list{max-height:180px}.checkgrid{grid-template-columns:1fr;gap:0;border:1px solid var(--line);border-radius:9px;overflow:hidden}.check{border:0;border-bottom:1px solid var(--line);border-radius:0;display:flex;justify-content:space-between;align-items:center;padding:9px 12px}.check:last-child{border:0}.check small{font-size:12px}.check b{font-size:14px}.result{padding-top:16px}.return strong{font-size:22px}.differences{font-size:11px}.differences td,.differences th{padding:8px 5px}.meta{gap:6px}.panel{padding:16px}.empty{min-height:150px}}
</style></head><body><header><b>稻草财经 <span class="muted">/ 账务核验</span></b><nav aria-label="研究导航"><a href="/api/quant-research/workspace">策略研究</a><a href="/api/quant-research/workspace?view=shares">股份档案</a></nav></header><div class="workspace"><div class="intro"><div><h1>账务核验</h1><p class="muted">策略结论与账务核验，分别记录。</p></div><button id="reload">刷新档案</button></div><div id="error" role="alert" class="hidden"></div><div id="login" class="panel hidden">请先<a href="/">返回首页登录</a>，再查看你的研究档案。</div><div id="content" class="layout hidden"><aside class="panel"><div class="sectionhead"><h3>我的核验档案</h3><span class="badge">只读</span></div><div id="records" class="list"></div><button id="next" class="hidden">更多档案</button></aside><main id="detail" class="panel detail" tabindex="-1"><div class="empty">选择档案，查看策略结论与逐笔差异。</div></main></div><footer>内部研究 · 事后重建。账务守恒不代表策略盈利、真实成交或税务清算通过。</footer></div><script>
'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=()=>{try{return localStorage.getItem('auth_token')||''}catch{return ''}};
let owned=token(),generation=0,selection=0,items=[],nextCursor=null,active=null,loading=false;
const date=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?'未知':d.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})};
const pct=v=>Number.isFinite(Number(v))?(Number(v)>0?'+':'')+Number(v).toFixed(2)+'%':'—';
const money=v=>Number.isSafeInteger(v)?(v/100).toFixed(2):'—';
function error(message){$('error').textContent=message;$('error').classList.toggle('hidden',!message)}
function report(e){if(!e.stale)error(e.name==='AbortError'?'读取超时，请稍后刷新':e.message)}
function reset(){generation++;selection++;loading=false;items=[];active=null;nextCursor=null;$('records').textContent='';$('detail').textContent='';$('content').classList.add('hidden');$('login').classList.toggle('hidden',!!token());$('reload').disabled=false;$('next').disabled=false;$('next').classList.add('hidden');error('')}
function session(g,t,s){if(g!==generation||t!==token()||s!=null&&s!==selection){if(g===generation&&t!==token())reset();const e=Error('Account changed');e.stale=true;throw e}}
async function api(path,s=null){const t=token(),g=generation;if(!t)throw Error('请先返回首页登录');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch('/api/quant-research'+path,{headers:{Authorization:'Bearer '+t},signal:controller.signal,cache:'no-store'});session(g,t,s);if(r.status===401){reset();$('login').classList.remove('hidden');throw Error('登录已过期，请返回首页重新登录')}if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error('档案服务暂不可用，请稍后重试');const data=await r.json();session(g,t,s);if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'档案读取未完成');return data}finally{clearTimeout(timer)}}
function drawList(){$('records').innerHTML=items.map(r=>`<button class="record" data-record="${esc(r.id)}" aria-current="${r.id===active}"><b>${esc(r.label)}</b><small>${esc(date(r.recorded_at))}</small><small>${Number(r.experiment_count)} 组原实验 · ${r.source_version_current?'查看核验':'旧版本档案'}</small></button>`).join('')||'<p class="muted">暂无核验档案。由内部管理员核对并导入原实验快照。</p>';$('next').classList.toggle('hidden',!nextCursor)}
async function load(more=false){if(loading)return;if(!token()){reset();return}const g=generation;loading=true;error('');$('reload').disabled=true;$('next').disabled=true;try{const data=await api('/model-cost-archives'+(more&&nextCursor?'?cursor='+encodeURIComponent(nextCursor):''));if(g!==generation)return;items=more?[...new Map([...items,...data.items].map(r=>[r.id,r])).values()]:data.items;nextCursor=data.next_cursor;$('login').classList.add('hidden');$('content').classList.remove('hidden');if(!more){active=null;$('detail').innerHTML='<div class="empty">选择档案，查看策略结论与逐笔差异。</div>'}drawList()}finally{if(g===generation){loading=false;$('reload').disabled=false;$('next').disabled=false}}}
function render(r){let html=`<h2>${esc(r.label)}</h2><div class="meta muted"><span>入库 ${esc(date(r.recorded_at))} · 北京时间</span><span>事后重建 · 已见资料</span></div>`;
if(!r.source_version_current||!r.experiments){$('detail').innerHTML=html+'<div class="notice">旧版本档案：仅显示历史入库信息，当前未重新核验账务；不展示核验指标。</div>';return}
html+='<p class="muted">展示已归档的核验结果；本页校验档案完整性，不重新运行策略。</p>';
for(const [i,e] of r.experiments.entries()){const passed=e.original_gate?.passed===true,balanced=e.exact_conservation_verified===true,legacy=e.legacy_strict_status==='strictly_reconciled',rejected=e.legacy_strict_status==='rejected';
html+=`<article class="result"><div class="resulthead"><div><h3>实验 ${String(i+1).padStart(2,'0')}</h3><p class="digest muted">${esc(e.experiment)}</p></div><div class="return"><small>原样本外收益率</small><strong class="${Number(e.original_oos_return_pct)<0?'loss':''}">${pct(e.original_oos_return_pct)}</strong></div></div><div class="checkgrid"><div class="check"><small>原策略门槛</small><b class="${passed?'verified':'failed'}">${passed?'通过原门槛':'未通过'}</b></div><div class="check"><small>归档账务守恒</small><b class="${balanced?'verified':'failed'}">${balanced?'已验证':'待核对'}</b></div><div class="check"><small>旧账务严格对账</small><b class="${legacy?'verified':'failed'}">${legacy?'一致':rejected?'未通过':'待核对'}</b></div></div>`;
if(!passed)html+=`<p class="muted">原失败原因：${(e.original_gate?.reasons||[]).map(esc).join('；')||'参见原实验'}</p>`;
html+=`<p class="stats">${Number(e.fills)} 笔成交 · ${Number(e.days)} 日核对 · 持仓恢复${e.restore?.full_state_and_outputs_equal?'一致':'待核对'}<br>旧记录差异 ${Number(e.legacy_difference_count)} 笔 · 精确舍入残差 ${esc(e.rounding_residual?.[0])}/${esc(e.rounding_residual?.[1])} 元</p>`;
if(e.differences?.length)html+=`<h3>逐笔盈亏差异</h3><div class="tablewrap"><table class="differences"><thead><tr><th>日期 / 证券</th><th>旧记录</th><th>新模型</th><th>旧－新</th></tr></thead><tbody>${e.differences.map(d=>`<tr><td>${esc(d.date)}<br><span class="muted">${esc(d.symbol)}</span></td><td>${money(d.legacy_cents)}</td><td>${money(d.exact_model_rounded_cents)}</td><td>${money(d.legacy_minus_exact_cents)}</td></tr>`).join('')}</tbody></table></div><p class="muted">单位：元。保留旧值，未回写或相互抵消。${e.differences_truncated?'仅显示前20笔，完整记录由内部管理员核对。':''}</p>`;
html+='</article>'}
html+=`<details><summary>审计标识与范围</summary><p class="digest">${esc(r.fingerprint)}</p><p class="muted">仅固定历史路径。尚未认证开盘成交、税基清算和完整时点数据；不开放交易或自动晋级。</p></details>`;$('detail').innerHTML=html}
async function selectArchive(id){const s=++selection;active=id;drawList();$('detail').textContent='正在核对档案…';const r=await api('/model-cost-archives/'+encodeURIComponent(id),s);if(s!==selection)return;render(r);if(window.innerWidth<=700){$('detail').scrollIntoView({behavior:'auto',block:'start'});$('detail').focus({preventScroll:true})}}
$('reload').addEventListener('click',()=>{selection++;load().catch(report)});$('next').addEventListener('click',()=>load(true).catch(report));document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.record)selectArchive(b.dataset.record).catch(report)});
window.addEventListener('storage',()=>{if(token()!==owned){owned=token();reset();load().catch(report)}});window.addEventListener('pagehide',reset);window.addEventListener('pageshow',e=>{if(e.persisted){owned=token();reset();load().catch(report)}});load().catch(report);
</script></body></html>'''
